 p=dest/(i+'.md');p.write_text(s);raw=hashlib.sha256(p.read_bytes()).hexdigest();expected=pre['hashes'][i]['item_sha256'];rows.append({'id':i,'candidate_path':str(p),'candidate_sha256':raw,'expected_pre_sha256':expected,'exact_match':raw==expected,'base':str(base),'operations':ops});print(i,raw,raw==expected)
